/**
 * AllDog bot — professional knowledge from the AllDog guides (all-dog.co.il/guides).
 *
 * knowledge-data.json is GENERATED by `npm run alldog:knowledge` (scripts/alldog-build-knowledge.ts)
 * from the site repo — never edit it by hand. lookupGuide() is a plain keyword search
 * (no vector DB): the model calls the lookup_guide tool with the customer's problem in a
 * few words and gets back the 1–2 best cards (insights + link).
 */
import knowledgeData from "@/lib/alldog-bot/knowledge-data.json";

export interface KnowledgeEntry {
  kind: "guide" | "tool";
  slug: string;
  category: string;
  title: string;
  url: string;
  topic: string;
  keywords: string[];
  insights: string[];
  whenToRecommend: string;
  sourceHash: string;
}

export interface KnowledgeFile {
  generatedAt: string;
  source: string;
  entries: KnowledgeEntry[];
}

export const KNOWLEDGE = knowledgeData as KnowledgeFile;

// Hebrew one-letter prefixes (ו ה ב ל מ ש כ) glued to words: "והחתולים" → "חתולים".
// Longest prefix first, so "וה" wins over "ו".
const PREFIX_RE = /^(?:וה|שה|וב|ול|ומ|כש|שב|של|מה|לה|בה|ו|ש|ה|ב|ל|מ|כ)(?=[\u0590-\u05FF]{3,})/u;
const STOP = new Set([
  "של", "את", "על", "עם", "זה", "הוא", "היא", "יש", "לא", "כל", "גם", "אבל", "או", "מה", "כלב", "הכלב", "כלבה",
  "הכלבה", "שלי", "שלנו", "אני", "אנחנו", "הוא", "מאוד", "כמו", "רק", "עוד", "כבר", "אחרי", "לפני", "כשהוא",
  "the", "a", "and",
]);

export function normalizeHe(text: string): string {
  return text
    .toLowerCase()
    .replace(/[֑-ׇ]/g, "") // niqqud / cantillation
    .replace(/[״"׳'`]/g, "")
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Tokens with and without a glued prefix, minus stop words. */
export function tokens(text: string): string[] {
  const out = new Set<string>();
  for (const w of normalizeHe(text).split(" ")) {
    if (w.length < 2 || STOP.has(w)) continue;
    out.add(w);
    const bare = w.replace(PREFIX_RE, "");
    if (bare !== w && bare.length >= 3 && !STOP.has(bare)) out.add(bare);
  }
  return [...out];
}

/** Two tokens match when equal or one is a prefix of the other (plural / suffix forms). */
function tokenMatch(a: string, b: string): boolean {
  if (a === b) return true;
  const [s, l] = a.length <= b.length ? [a, b] : [b, a];
  return s.length >= 3 && l.startsWith(s) && l.length - s.length <= 3;
}

function overlap(query: string[], field: string[]): number {
  let n = 0;
  for (const q of query) if (field.some((f) => tokenMatch(q, f))) n++;
  return n;
}

export interface GuideMatch {
  entry: KnowledgeEntry;
  score: number;
}

// ─── The main problem wins over side words (Or, item 29a) ──────────────────────
// "תוקף כלבים ומושך קדימה" is aggression / reactivity toward dogs, not leash pulling: when the topic
// names one of these problems, its guides are returned first and side topics (leash, breed) drop out.

const V = "(?:ו|ש|וש|כש)?";
/** Toward people: bit / attacks a person. */
const PEOPLE_AGGRESSION_RE = new RegExp(
  `${V}(?:נשך|נשכה|נושך|נושכת|נשיכה|נשיכות|תוקף|תוקפת|תקף|תקפה|מתקיף|מתקיפה|מתנפל|מתנפלת|נוהם|נוהמת)\\s+(?:\\S+\\s+){0,3}?(?:את\\s+)?(?:ה(?:בן|בת)|(?:ה)?(?:אנשים|אדם|ילד|ילדה|ילדים|אחיין|אחיינית|אורח|אורחים|שכן|שכנה|שכנים|אותי|אותנו|בעלי|אשתי|תינוק|זרים))(?![\\p{L}])`,
  "u"
);
/** Toward dogs — attack words. */
const DOG_ATTACK_RE = new RegExp(
  `${V}(?:תוקף|תוקפת|תקף|תקפה|מתקיף|מתקיפה|תוקפני|תוקפנית|נושך|נושכת|נשך|נשכה|רב|רבה|נלחם|נלחמת)\\s+(?:\\S+\\s+){0,3}?(?:את\\s+)?(?:על\\s+|ב|ל|ה)?(?:ה)?כלב(?:ים|ה|ות)?(?![\\p{L}])|תוקפנות\\s+(?:כלפי|ל|על)\\s*(?:ה)?כלב`,
  "u"
);
/** Toward dogs — reactivity words (barks / lunges / goes wild when it sees a dog). */
const DOG_REACTIVE_RE = new RegExp(
  `${V}(?:מתפרץ|מתפרצת|מתנפל|מתנפלת|נובח|נובחת|משתולל|משתוללת|מסתער|מסתערת|משתגע|משתגעת|מושך|מושכת|קופץ|קופצת|מגיב|מגיבה)\\s+(?:\\S+\\s+){0,4}?(?:על\\s+|ל|ב|כש?רואה\\s+|ליד\\s+)?(?:ה)?כלב(?:ים|ה|ות)?(?![\\p{L}])|תגובתי|ריאקטיב`,
  "u"
);

/** The guides of the main problem the topic names, most relevant first (empty = no main problem). */
export function primaryProblemSlugs(topic: string): string[] {
  const t = normalizeHe(topic);
  if (PEOPLE_AGGRESSION_RE.test(t)) return ["dog-aggression", "reactive-dog"];
  if (DOG_ATTACK_RE.test(t)) return ["dog-aggression", "reactive-dog"];
  if (DOG_REACTIVE_RE.test(t)) return ["reactive-dog", "dog-aggression"];
  return [];
}

/** Best entries for a free-text topic, highest score first (score > 0 only). */
export function searchKnowledge(topic: string, entries: KnowledgeEntry[] = KNOWLEDGE.entries, limit = 2): GuideMatch[] {
  const primary = primaryProblemSlugs(topic);
  if (primary.length) {
    const found = primary
      .map((slug, i) => ({ entry: entries.find((e) => e.slug === slug), score: 1000 - i }))
      .filter((m): m is GuideMatch => !!m.entry);
    if (found.length) return found.slice(0, limit);
  }
  const q = tokens(topic);
  if (!q.length) return [];
  const qNorm = normalizeHe(topic);
  const scored = entries.map((entry) => {
    let score = 0;
    for (const k of entry.keywords) {
      const kn = normalizeHe(k);
      if (kn.length >= 3 && qNorm.includes(kn)) score += 6; // whole keyword phrase in the query
      score += 2 * overlap(q, tokens(k));
    }
    score += 3 * overlap(q, tokens(entry.topic));
    score += 2 * overlap(q, tokens(entry.title));
    score += overlap(q, tokens(entry.whenToRecommend));
    return { entry, score };
  });
  const best = scored.filter((s) => s.score > 0).sort((a, b) => b.score - a.score);
  if (!best.length) return [];
  // Keep the runner-up only when it is close (a second, related guide), never noise.
  return best.slice(0, limit).filter((m, i) => i === 0 || m.score >= best[0].score * 0.6);
}

/** Text returned to the model by the lookup_guide tool. */
export function lookupGuide(topic: string, entries: KnowledgeEntry[] = KNOWLEDGE.entries): string {
  const matches = searchKnowledge(topic, entries);
  if (!matches.length) {
    return "לא נמצא מדריך מתאים. אל תמציא ידע מקצועי: משפט אמפתי אחד, ושהמאלף יעבור על זה בשיחה או באבחון.";
  }
  const blocks = matches.map(({ entry }) =>
    [
      `${entry.kind === "tool" ? "כלי" : "מדריך"}: ${entry.title}`,
      `קישור: ${entry.url}`,
      `נושא: ${entry.topic}`,
      `מתי להמליץ: ${entry.whenToRecommend}`,
      "תובנות:",
      ...entry.insights.map((i) => `- ${i}`),
    ].join("\n")
  );
  return [
    ...blocks,
    "",
    "שימוש: משפט אחד–שניים במילים שלך מתוך התובנות (לא העתקה, לא תוכנית אילוף, לא אבחון). את הקישור למדריך לא שולחים ולא מציעים: המערכת מציעה אותו ללקוח בעצמה בהמשך. מיד אחר כך חוזרים לשיחה ומובילים לשיחה עם נציגה או לאבחון. (כלי חירום כמו מחשבון שוקולד: שולחים את הקישור שלו מיד.)",
  ].join("\n\n");
}
